import{_ as a,o as e,c as o,a2 as s}from"./chunks/framework.CdvW4CUT.js";const d="/assets/shots/schedule.png",r="/assets/shots/monitor.png",b=JSON.parse('{"title":"监控与续期","description":"站点证书巡检、定时续期、到期提醒与失败兜底，让证书永不过期。","frontmatter":{"title":"监控与续期","description":"站点证书巡检、定时续期、到期提醒与失败兜底，让证书永不过期。"},"headers":[],"relativePath":"docs/monitor.md","filePath":"docs/monitor.md","lastUpdated":null}'),i={name:"docs/monitor.md"};function n(l,t,c,h,p,u){return e(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="监控与续期" tabindex="-1">监控与续期 <a class="header-anchor" href="#监控与续期" aria-label="Permalink to &quot;监控与续期&quot;">​</a></h1><p>证书管理的真正成本不在签发，而在「别忘了续」。CertHub 用三层机制兜住：<strong>定时续期 + 站点巡检 + 到期提醒</strong>。</p><h2 id="定时续期" tabindex="-1">定时续期 <a class="header-anchor" href="#定时续期" aria-label="Permalink to &quot;定时续期&quot;">​</a></h2><p><img src="'+d+'" alt="定时任务"></p><p>流水线详情页右上角 <strong>定时任务</strong>，按日历选（每天 / 每周 / 每月 1 日 / 自定义 cron），按钮上直接显示人话时间，例如「每天 03:00」。</p><p>保存后写回 <code>content.triggers</code>，<strong>下次运行时间由后端立即重算</strong>，不用等调度器下一轮 tick。停用会清空下次执行时间，重新启用会按当前 cron 再算一遍。</p><div class="tip custom-block"><p class="custom-block-title">为什么可以「每天跑一次」</p><p>证书任务里有 <code>renewDays</code>（默认 20 天）：没到续期时间就自动跳过签发，直接复用证书库里的证书。所以定时任务设成每天跑是安全的，不会反复申请触发 CA 限流。</p></div><p>几个相关的开关：</p><table tabindex="0"><thead><tr><th>开关</th><th>作用</th></tr></thead><tbody><tr><td>提前续期天数</td><td>距离到期小于这个天数才重新签</td></tr><tr><td>强制续期</td><td>忽略剩余天数，立刻重签（换 CA、换密钥类型时用）</td></tr><tr><td>证书已存在且未过期就跳过</td><td>默认开启</td></tr><tr><td>刚申请过就跳过（分钟）</td><td>防止短时间重复触发</td></tr></tbody></table><h2 id="站点监控" tabindex="-1">站点监控 <a class="header-anchor" href="#站点监控" aria-label="Permalink to &quot;站点监控&quot;">​</a></h2><p><img src="'+r+`" alt="站点监控"></p><p><strong>站点监控</strong> 用来盯住那些<strong>不由本平台签发</strong>的证书（别人家的站点、云厂商托管的证书、还没接管的存量站点）。</p><ul><li>录入 URL 即可，系统定时探测 443 端口，读取证书状态、签发者、到期时间、剩余天数与最近巡检时间。</li><li>列表中用「正常 / 即将到期 / 异常」标色，异常站点可以和流水线联动修复。</li><li>可以手动点「巡检」立即刷新。</li></ul><h2 id="到期提醒" tabindex="-1">到期提醒 <a class="header-anchor" href="#到期提醒" aria-label="Permalink to &quot;到期提醒&quot;">​</a></h2><p>系统设置 → 通知 → <strong>到期提醒天数</strong>（默认 15 天）。证书进入提醒窗口后，通过默认通知渠道推送；站点监控发现异常也会推。</p><p>生产环境建议至少配一个即时通讯类渠道（钉钉 / 企微 / 飞书机器人），确保续期失败能第一时间触达。</p><h2 id="失败兜底" tabindex="-1">失败兜底 <a class="header-anchor" href="#失败兜底" aria-label="Permalink to &quot;失败兜底&quot;">​</a></h2><ul><li><strong>失败后跳转</strong>：任务配置底部可以选「失败后跳转到」后面某个任务，画布上会多一条橙色虚线。常见用法是「申请失败 → 跳到通知任务」，避免失败静默。</li><li><strong>单入边</strong>：一个任务最多只有一条「失败后」入边，被占用时下拉项会置灰并注明占用者。</li><li><strong>协作式停止</strong>：执行中可以点「停止」，在任务之间与 ACME 轮询的每一轮检查标志位。</li><li><strong>进程被强杀</strong>：启动时会把遗留的 <code>running</code> 记录标成 <code>failed</code> 并补一句「服务重启，本次执行已中断」，前端不会一直转圈。</li></ul><h2 id="健康检查" tabindex="-1">健康检查 <a class="header-anchor" href="#健康检查" aria-label="Permalink to &quot;健康检查&quot;">​</a></h2><p><code>GET /api/health</code>：</p><ul><li>正常返回 <code>code=200</code>；</li><li>数据库不可用 / 磁盘 &lt; 200MB / 调度器没起来时返回 <strong>503</strong>，并在 <code>data</code> 里给出原因。</li></ul><p>用 Uptime Kuma、云监控或宝塔告警盯这个地址即可。它同时也是容器 <code>HEALTHCHECK</code> 用的探针。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000/api/health</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># {&quot;code&quot;:200,&quot;data&quot;:{&quot;db&quot;:&quot;ok&quot;,&quot;scheduler&quot;:&quot;running&quot;,&quot;diskFreeMb&quot;:...}}</span></span></code></pre></div><h2 id="容量" tabindex="-1">容量 <a class="header-anchor" href="#容量" aria-label="Permalink to &quot;容量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>默认</th><th>怎么改</th></tr></thead><tbody><tr><td>每条流水线的执行历史</td><td>保留 20 条</td><td>流水线「定时任务」抽屉里的「保留条数」</td></tr><tr><td>备份份数</td><td>14 份</td><td><code>tools/backup.py --keep N</code></td></tr><tr><td>证书文件</td><td>每次签发一份，不自动删</td><td>证书库删除后文件仍在 <code>data/certs</code>，可按需清理旧目录</td></tr></tbody></table><p>数据目录持续变大时，先看执行历史保留条数与 <code>data/certs</code> 的旧目录。</p>`,26)])])}const k=a(i,[["render",n]]);export{b as __pageData,k as default};
